<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';

interface EventItem { id: number; name: string; type: string; event_date: string | null; event_time: string | null; starts_at: string | null; venue: string | null; address: string | null; is_primary: boolean }
interface Member { id: number; relationship: string; permissions: Record<string, boolean> | null; user: { name: string; email: string; role: string } }
interface Expansion { id: number; requested_count: number; status: string; reason: string | null; additional_cost: string | null; decision_reason: string | null; proposal_version: number }
interface Service { id: number; name: string; owner: string; status: string; estimated_cost: string | null }
interface Responsibility { id: number; label: string; owner: string; status: string; due_date: string | null; notes: string | null }
interface Wedding { id: number; name: string; status: string; support_type: string; timezone: string; authorized_capacity: number | null; interview: { status: string } | null; events: EventItem[]; memberships: Member[]; services: Service[]; responsibilities: Responsibility[]; capacity_expansion_requests: Expansion[] }
const props = defineProps<{ wedding: Wedding; serverNow: string; canEdit: boolean; canRequestCapacity: boolean; canRespondCapacity: boolean; isAdmin: boolean; canReceive: boolean; serviceTemplates: { id: number; name: string; category: string | null; default_owner: string }[] }>();
const now = ref(new Date(props.serverNow).getTime());
let timer: number | undefined;
onMounted(() => { timer = window.setInterval(() => { now.value += 60_000; }, 60_000); });
onBeforeUnmount(() => { if (timer) window.clearInterval(timer); });

const primaryEvent = computed(() => props.wedding.events.find((event) => event.is_primary) ?? props.wedding.events[0]);
function countdown(event?: EventItem): string {
    if (!event?.event_date) return 'Fecha pendiente';
    if (!event.starts_at) return `Faltan ${Math.max(0, Math.ceil((new Date(`${event.event_date}T00:00:00`).getTime() - now.value) / 86_400_000))} días · hora pendiente`;
    const minutes = Math.max(0, Math.ceil((new Date(event.starts_at).getTime() - now.value) / 60_000));
    if (minutes === 0) return 'El evento principal ya inició';
    return `${Math.floor(minutes / 1_440)} días · ${Math.floor((minutes % 1_440) / 60)} h · ${minutes % 60} min`;
}
function saveEvent(event: EventItem): void {
    router.put(route('weddings.events.update', [props.wedding.id, event.id]), event, { preserveScroll: true, preserveState: true, replace: true });
}
function deleteEvent(event: EventItem): void { if (window.confirm(`¿Eliminar el evento “${event.name}”?`)) router.delete(route('weddings.events.destroy', [props.wedding.id, event.id]), { preserveScroll: true, preserveState: true, replace: true }); }
const serviceForm = useForm({ wedding_service_template_id: null as number | null, name: '', owner: 'company' });
const responsibilityForm = useForm({ label: '', owner: 'company', due_date: '', notes: '' });
const weddingForm = useForm({ name: props.wedding.name, status: props.wedding.status, support_type: props.wedding.support_type, authorized_capacity: props.wedding.authorized_capacity as number | null, timezone: props.wedding.timezone });
const editingWedding = ref(false);
const editingService = ref<number | null>(null);
const editingResponsibility = ref<number | null>(null);
const serviceEditForm = useForm({ name: '', owner: 'company', status: 'included', estimated_cost: null as number | null, details: null as Record<string, unknown> | null });
const responsibilityEditForm = useForm({ label: '', owner: 'company', status: 'pending', due_date: '', notes: '' });
const expansionForm = useForm({ requested_count: 1, reason: '' });
const proposalForm = useForm({ additional_cost: 0, decision_reason: '' });
const visitOptions = { preserveScroll: true, preserveState: true, replace: true };
function saveWedding(): void { weddingForm.patch(route('weddings.update', props.wedding.id), { ...visitOptions, onSuccess: () => { editingWedding.value = false; } }); }
function addService(): void { serviceForm.post(route('weddings.services.store', props.wedding.id), { ...visitOptions, onSuccess: () => serviceForm.reset() }); }
function editService(service: Service): void { editingService.value = service.id; serviceEditForm.name = service.name; serviceEditForm.owner = service.owner; serviceEditForm.status = service.status; serviceEditForm.estimated_cost = service.estimated_cost === null ? null : Number(service.estimated_cost); }
function saveService(service: Service): void { serviceEditForm.patch(route('weddings.services.update', [props.wedding.id, service.id]), { ...visitOptions, onSuccess: () => { editingService.value = null; serviceEditForm.reset(); } }); }
function deleteService(service: Service): void { if (window.confirm(`¿Eliminar el servicio “${service.name}”?`)) router.delete(route('weddings.services.destroy', [props.wedding.id, service.id]), visitOptions); }
function addResponsibility(): void { responsibilityForm.post(route('weddings.responsibilities.store', props.wedding.id), { ...visitOptions, onSuccess: () => responsibilityForm.reset() }); }
function editResponsibility(item: Responsibility): void { editingResponsibility.value = item.id; responsibilityEditForm.label = item.label; responsibilityEditForm.owner = item.owner; responsibilityEditForm.status = item.status; responsibilityEditForm.due_date = item.due_date ?? ''; responsibilityEditForm.notes = item.notes ?? ''; }
function saveResponsibility(item: Responsibility): void { responsibilityEditForm.patch(route('weddings.responsibilities.update', [props.wedding.id, item.id]), { ...visitOptions, onSuccess: () => { editingResponsibility.value = null; responsibilityEditForm.reset(); } }); }
function deleteResponsibility(item: Responsibility): void { if (window.confirm(`¿Eliminar la responsabilidad “${item.label}”?`)) router.delete(route('weddings.responsibilities.destroy', [props.wedding.id, item.id]), visitOptions); }
function requestExpansion(): void { expansionForm.post(route('weddings.capacity-expansions.store', props.wedding.id), { preserveScroll: true, onSuccess: () => expansionForm.reset() }); }
function proposeExpansion(item: Expansion): void { proposalForm.patch(route('weddings.capacity-expansions.propose', [props.wedding.id, item.id]), { preserveScroll: true }); }
function respondExpansion(item: Expansion, decision: 'accepted' | 'rejected'): void { router.patch(route('weddings.capacity-expansions.respond', [props.wedding.id, item.id]), { decision }, { preserveScroll: true }); }
function authorizeExpansion(item: Expansion): void { router.patch(route('weddings.capacity-expansions.resolve', [props.wedding.id, item.id]), { decision: 'approved' }, { preserveScroll: true }); }
function setPermission(member: Member, key: string, value: boolean): void { router.patch(route('weddings.memberships.permissions', [props.wedding.id, member.id]), { permissions: { ...(member.permissions ?? {}), [key]: value } }, { preserveScroll: true }); }
function setPermissionFromEvent(member: Member, key: string, event: Event): void { setPermission(member, key, (event.target as HTMLInputElement).checked); }
const permissionLabels: Record<string, string> = { view_progress: 'Consultar avance', edit_wedding: 'Editar expediente', create_requests: 'Crear solicitudes', approve_proposals: 'Aprobar propuestas', share_invitation: 'Compartir invitaciones', view_finance: 'Ver finanzas', scan_passes: 'Registrar recepción' };
</script>

<template>
    <Head :title="wedding.name" />
    <AuthenticatedLayout>
        <template #header>
<div class="flex flex-wrap items-center justify-between gap-4"><div><Link :href="route('dashboard')" class="text-sm text-rose-800 underline underline-offset-4">← Inicio</Link><h1 class="mt-1 font-serif text-3xl text-stone-800">{{ wedding.name }}</h1></div><div class="flex gap-2"><Link :href="route('weddings.planning.index', wedding.id)" class="rounded-lg border border-stone-700 px-4 py-2 text-sm font-medium text-stone-800">Planeación</Link><Link v-if="canReceive" :href="route('weddings.reception.index', wedding.id)" class="rounded-lg border border-stone-700 px-4 py-2 text-sm font-medium text-stone-800">Recepción</Link><Link v-if="canEdit" :href="route('weddings.families.index', wedding.id)" class="rounded-lg border border-rose-700 px-4 py-2 text-sm font-medium text-rose-800">Familias</Link><Link v-if="canEdit" :href="route('weddings.interview.edit', wedding.id)" class="rounded-lg bg-rose-800 px-4 py-2 text-sm font-medium text-white hover:bg-rose-900 focus:outline-none focus:ring-2 focus:ring-rose-500">Continuar entrevista</Link></div></div>
        </template>
        <div class="mx-auto max-w-6xl space-y-6 px-4 py-8 sm:px-6 lg:px-8">
            <section class="rounded-2xl bg-stone-800 p-6 text-white sm:p-8"><p class="text-sm uppercase tracking-[.2em] text-rose-200">Evento principal · {{ wedding.timezone }}</p><h2 class="mt-2 font-serif text-3xl">{{ primaryEvent?.name || 'Evento por definir' }}</h2><p class="mt-2 text-stone-200">{{ primaryEvent?.event_date || 'Fecha pendiente' }}<span v-if="primaryEvent?.event_time"> · {{ primaryEvent.event_time }}</span><span v-if="primaryEvent?.venue"> · {{ primaryEvent.venue }}</span></p><p class="mt-5 text-xl font-semibold text-rose-100">{{ countdown(primaryEvent) }}</p></section>

            <div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl text-stone-800">Eventos</h2><div v-for="event in wedding.events" :key="event.id" class="mt-5 border-t border-stone-100 pt-4"><template v-if="canEdit"><form @submit.prevent="saveEvent(event)" class="grid gap-3 sm:grid-cols-2"><label class="text-sm text-stone-700">Nombre<input v-model="event.name" class="mt-1 w-full rounded-lg border-stone-300" required></label><label class="text-sm text-stone-700">Tipo<select v-model="event.type" class="mt-1 w-full rounded-lg border-stone-300"><option value="reception">Recepción</option><option value="ceremony">Ceremonia</option><option value="civil">Civil</option><option value="after_party">Tornaboda</option><option value="other">Otro</option></select></label><label class="text-sm text-stone-700">Fecha<input v-model="event.event_date" type="date" class="mt-1 w-full rounded-lg border-stone-300"></label><label class="text-sm text-stone-700">Hora<input v-model="event.event_time" type="time" class="mt-1 w-full rounded-lg border-stone-300"></label><label class="text-sm text-stone-700 sm:col-span-2">Lugar<input v-model="event.venue" class="mt-1 w-full rounded-lg border-stone-300"></label><div class="flex gap-3"><button class="rounded-lg border border-rose-700 px-3 py-2 text-sm font-medium text-rose-800">Guardar evento</button><button type="button" class="text-sm text-red-700 underline" @click="deleteEvent(event)">Eliminar</button></div></form></template><template v-else><p class="font-medium text-stone-800">{{ event.name }}</p><p class="text-sm text-stone-600">{{ event.event_date || 'Fecha pendiente' }} · {{ event.event_time || 'Hora pendiente' }} · {{ event.venue || 'Lugar pendiente' }}</p></template></div></section>
                <section class="rounded-2xl border border-stone-200 bg-white p-6"><div class="flex items-center justify-between gap-3"><h2 class="font-serif text-2xl text-stone-800">Configuración</h2><button v-if="canEdit" type="button" class="text-sm text-rose-800 underline" @click="editingWedding = !editingWedding">{{ editingWedding ? 'Cancelar edición' : 'Editar expediente' }}</button></div><form v-if="canEdit && editingWedding" class="mt-4 grid gap-3 sm:grid-cols-2" @submit.prevent="saveWedding"><label class="text-sm">Nombre<input v-model="weddingForm.name" required class="mt-1 w-full rounded border-stone-300"></label><label class="text-sm">Estado<select v-model="weddingForm.status" class="mt-1 w-full rounded border-stone-300"><option value="consultation">Consulta</option><option value="contracted">Contratada</option><option value="preparation">Preparación</option></select></label><label class="text-sm">Acompañamiento<select v-model="weddingForm.support_type" class="mt-1 w-full rounded border-stone-300"><option value="full">Integral</option><option value="shared">Compartida</option><option value="advisory">Asesoría</option></select></label><label class="text-sm">Cupo autorizado<input v-model.number="weddingForm.authorized_capacity" type="number" min="1" class="mt-1 w-full rounded border-stone-300"></label><label class="text-sm sm:col-span-2">Zona horaria<input v-model="weddingForm.timezone" required class="mt-1 w-full rounded border-stone-300"></label><button :disabled="weddingForm.processing" class="justify-self-start rounded bg-rose-800 px-3 py-2 text-sm text-white">Guardar expediente</button></form><dl v-else class="mt-4 space-y-3 text-sm"><div class="flex justify-between gap-4"><dt class="text-stone-500">Acompañamiento</dt><dd class="font-medium text-stone-800">{{ wedding.support_type }}</dd></div><div class="flex justify-between gap-4"><dt class="text-stone-500">Cupo autorizado</dt><dd class="font-medium text-stone-800">{{ wedding.authorized_capacity || 'Pendiente' }}</dd></div><div class="flex justify-between gap-4"><dt class="text-stone-500">Estado</dt><dd class="font-medium text-stone-800">{{ wedding.interview?.status === 'active' ? 'Activa' : 'Borrador' }}</dd></div></dl><button v-if="canEdit && wedding.interview?.status !== 'active'" class="mt-6 rounded-lg bg-rose-800 px-4 py-2 text-sm font-medium text-white" @click="router.post(route('weddings.configuration.activate', wedding.id), {}, visitOptions)">Activar configuración revisada</button><h3 class="mt-7 font-medium text-stone-800">Accesos efectivos</h3><div v-for="member in wedding.memberships" :key="member.id" class="mt-3 border-t border-stone-100 pt-3 text-sm"><p><span class="font-medium text-stone-800">{{ member.user.name }}</span> · {{ member.relationship }}</p><div v-if="canEdit" class="mt-2 flex flex-wrap gap-x-4 gap-y-2"> <label v-for="(label, key) in permissionLabels" :key="key" class="flex items-center gap-1 text-stone-600"><input type="checkbox" :checked="member.permissions?.[key] ?? false" @change="setPermission(member, key, ($event.target as HTMLInputElement).checked)">{{ label }}</label></div><p v-else class="mt-1 text-stone-600">{{ Object.keys(member.permissions ?? {}).filter((key) => member.permissions?.[key]).join(', ') || 'Sin acciones' }}</p></div></section></div>
            <div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl text-stone-800">Servicios contratados</h2><article v-for="service in wedding.services" :key="service.id" class="mt-4 border-t pt-3 text-sm"><template v-if="editingService === service.id"><form class="grid gap-2" @submit.prevent="saveService(service)"><input v-model="serviceEditForm.name" required class="rounded border-stone-300"><div class="grid grid-cols-2 gap-2"><select v-model="serviceEditForm.owner" class="rounded border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select><select v-model="serviceEditForm.status" class="rounded border-stone-300"><option value="included">Incluido</option><option value="pending">Pendiente</option><option value="confirmed">Confirmado</option><option value="cancelled">Cancelado</option></select></div><input v-model.number="serviceEditForm.estimated_cost" type="number" min="0" step="0.01" class="rounded border-stone-300" placeholder="Costo estimado"><div class="flex gap-2"><button class="rounded bg-rose-800 px-3 py-1 text-white">Guardar</button><button type="button" class="rounded border px-3 py-1" @click="editingService = null">Cancelar</button></div></form></template><template v-else><p class="font-medium">{{ service.name }}</p><p class="text-stone-600">{{ service.owner }} · {{ service.status }}<span v-if="service.estimated_cost"> · ${{ service.estimated_cost }}</span></p><div v-if="canEdit" class="mt-2 flex gap-3"><button type="button" class="text-rose-800 underline" @click="editService(service)">Editar</button><button type="button" class="text-red-700 underline" @click="deleteService(service)">Eliminar</button></div></template></article><p v-if="!wedding.services.length" class="mt-4 text-sm text-stone-500">Aún no se han definido servicios.</p><form v-if="canEdit" class="mt-5 grid gap-3" @submit.prevent="addService"><input v-model="serviceForm.name" list="service-templates" placeholder="Servicio contratado" required class="rounded-lg border-stone-300"><datalist id="service-templates"><option v-for="template in serviceTemplates" :key="template.id" :value="template.name" /></datalist><select v-model="serviceForm.owner" class="rounded-lg border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select><button :disabled="serviceForm.processing" class="justify-self-start rounded-lg border border-rose-700 px-3 py-2 text-sm text-rose-800">Agregar servicio</button></form></section><section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl text-stone-800">Responsabilidades</h2><article v-for="item in wedding.responsibilities" :key="item.id" class="mt-4 border-t pt-3 text-sm"><template v-if="editingResponsibility === item.id"><form class="grid gap-2" @submit.prevent="saveResponsibility(item)"><input v-model="responsibilityEditForm.label" required class="rounded border-stone-300"><div class="grid grid-cols-2 gap-2"><select v-model="responsibilityEditForm.owner" class="rounded border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select><select v-model="responsibilityEditForm.status" class="rounded border-stone-300"><option value="pending">Pendiente</option><option value="in_progress">En proceso</option><option value="completed">Completada</option><option value="cancelled">Cancelada</option></select></div><input v-model="responsibilityEditForm.due_date" type="date" class="rounded border-stone-300"><textarea v-model="responsibilityEditForm.notes" class="rounded border-stone-300" placeholder="Notas"></textarea><div class="flex gap-2"><button class="rounded bg-rose-800 px-3 py-1 text-white">Guardar</button><button type="button" class="rounded border px-3 py-1" @click="editingResponsibility = null">Cancelar</button></div></form></template><template v-else><p class="font-medium">{{ item.label }}</p><p class="text-stone-600">{{ item.owner }} · {{ item.status }}<span v-if="item.due_date"> · {{ item.due_date }}</span></p><p v-if="item.notes" class="text-stone-500">{{ item.notes }}</p><div v-if="canEdit" class="mt-2 flex gap-3"><button type="button" class="text-rose-800 underline" @click="editResponsibility(item)">Editar</button><button type="button" class="text-red-700 underline" @click="deleteResponsibility(item)">Eliminar</button></div></template></article><p v-if="!wedding.responsibilities.length" class="mt-4 text-sm text-stone-500">Aún no se han definido responsabilidades.</p><form v-if="canEdit" class="mt-5 grid gap-3" @submit.prevent="addResponsibility"><input v-model="responsibilityForm.label" placeholder="Responsabilidad" required class="rounded-lg border-stone-300"><select v-model="responsibilityForm.owner" class="rounded-lg border-stone-300"><option value="company">Empresa</option><option value="couple">Pareja</option><option value="shared">Compartida</option></select><input v-model="responsibilityForm.due_date" type="date" class="rounded-lg border-stone-300"><textarea v-model="responsibilityForm.notes" class="rounded-lg border-stone-300" placeholder="Notas"></textarea><button :disabled="responsibilityForm.processing" class="justify-self-start rounded-lg border border-rose-700 px-3 py-2 text-sm text-rose-800">Agregar responsabilidad</button></form></section></div>
            <section class="rounded-2xl border border-stone-200 bg-white p-6"><h2 class="font-serif text-2xl text-stone-800">Ampliaciones de cupo</h2><p class="mt-1 text-sm text-stone-600">Una ampliación aprobada aumenta el cupo total, pero nunca asigna pases a una familia por sí sola.</p><form v-if="canRequestCapacity" class="mt-4 grid gap-3 sm:grid-cols-3" @submit.prevent="requestExpansion"><input v-model.number="expansionForm.requested_count" type="number" min="1" placeholder="Lugares" class="rounded-lg border-stone-300"><input v-model="expansionForm.reason" maxlength="1000" placeholder="Motivo (opcional)" class="rounded-lg border-stone-300 sm:col-span-2"><button class="justify-self-start rounded-lg border border-rose-700 px-3 py-2 text-sm text-rose-800">Solicitar ampliación</button></form><div v-for="item in wedding.capacity_expansion_requests" :key="item.id" class="mt-5 rounded-xl border border-stone-100 p-4 text-sm"><p class="font-medium text-stone-800">{{ item.requested_count }} lugares · {{ item.status }}<span v-if="item.proposal_version"> · propuesta v{{ item.proposal_version }}</span></p><p v-if="item.reason" class="mt-1 text-stone-600">{{ item.reason }}</p><p v-if="item.additional_cost !== null" class="mt-1 text-stone-600">Costo adicional: ${{ item.additional_cost }}</p><p v-if="item.decision_reason" class="mt-1 text-stone-600">{{ item.decision_reason }}</p><form v-if="isAdmin && (item.status === 'pending' || item.status === 'proposed')" class="mt-3 flex flex-wrap gap-2" @submit.prevent="proposeExpansion(item)"><input v-model.number="proposalForm.additional_cost" type="number" min="0" step="0.01" class="w-32 rounded-lg border-stone-300" aria-label="Costo adicional"><input v-model="proposalForm.decision_reason" placeholder="Condiciones para la pareja" class="rounded-lg border-stone-300"><button class="rounded border border-rose-700 px-3 py-1 text-rose-800">Enviar propuesta</button></form><div v-if="canRespondCapacity && item.status === 'proposed'" class="mt-3 flex gap-2"><button class="rounded bg-rose-800 px-3 py-1 text-white" @click="respondExpansion(item, 'accepted')">Aceptar propuesta</button><button class="rounded border border-stone-400 px-3 py-1 text-stone-700" @click="respondExpansion(item, 'rejected')">Rechazar</button></div><button v-if="isAdmin && item.status === 'accepted'" class="mt-3 rounded bg-stone-800 px-3 py-1 text-white" @click="authorizeExpansion(item)">Autorizar ampliación final</button></div><p v-if="!wedding.capacity_expansion_requests.length" class="mt-4 text-sm text-stone-500">No hay solicitudes de ampliación.</p></section>
        </div>
    </AuthenticatedLayout>
</template>
